import{_ as a,a as s}from"./chunks/jobbench_leaderboard_en.CkH94sFC.js";import{c as n,Q as t,j as o,m as r}from"./chunks/framework.t4rEqR7d.js";const b=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md"}'),i={name:"benchmarks.md"};function l(d,e,p,h,c,g){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h1><p>We ran <a href="https://job-bench.github.io/" target="_blank" rel="noreferrer">JobBench</a> with <code>deepseek-v4-flash</code> as the player, comparing two harnesses — the official <strong>OpenCode</strong> and pagentv4&#39;s <strong>inplace</strong> mode (<code>CodeRunner + InplaceBackend</code>). Both use the same player model and the same judge (<code>deepseek-v4-pro</code>, temperature 0), so only the harness and the split change.</p><div class="warning custom-block"><p class="custom-block-title">Judge differs from the official leaderboard</p><p>The official leaderboard is judged by <strong>Grok 4.3</strong>. We judge with <strong>deepseek-v4-pro</strong> (same vendor as the player, so scores run lenient). Our numbers are indicative only and <strong>not directly comparable</strong> to the official board. That is why our rows are marked with <code>*</code>.</p></div><h2 id="opencode-vs-pagentv4" tabindex="-1">OpenCode vs pagentv4 <a class="header-anchor" href="#opencode-vs-pagentv4" aria-label="Permalink to &quot;OpenCode vs pagentv4&quot;">​</a></h2><p>Same player, same judge — swapping only the harness. pagentv4 leads on both splits.</p><p><img src="'+a+'" alt="OpenCode vs pagentv4 on JobBench Easy and Main splits — pagentv4 leads micro score by +4.5 on Easy and +1.6 on Main"></p><ul><li><strong>Easy split:</strong> pagentv4 <strong>80.0</strong> vs OpenCode 75.5 (micro).</li><li><strong>Main split:</strong> pagentv4 <strong>38.2</strong> vs OpenCode 36.6 (micro).</li><li>On Main, pagentv4 produced 5 tasks scoring ≥0.8 (one perfect) against OpenCode&#39;s 1.</li></ul><p><code>micro</code> = total score / max score (rubric-weighted). <code>macro</code> = mean of per-task normalized scores.</p><h2 id="where-it-lands-on-the-main-leaderboard" tabindex="-1">Where it lands on the Main leaderboard <a class="header-anchor" href="#where-it-lands-on-the-main-leaderboard" aria-label="Permalink to &quot;Where it lands on the Main leaderboard&quot;">​</a></h2><p>The official board only counts the Main split. Dropping our two harness runs into that ranking (judge differs, so this is illustrative):</p><p><img src="'+s+`" alt="JobBench Main split leaderboard with deepseek-v4-flash under pagentv4 at 38.2 and OpenCode at 36.6, placed between GPT-5.5 and Claude Sonnet 4.6"></p><ul><li><strong>pagentv4 = 38.2</strong> lands between GPT-5.5 (38.3) and Claude Sonnet 4.6 (36.6).</li><li><strong>OpenCode = 36.6</strong> ties with Claude Sonnet 4.6.</li></ul><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to &quot;Reproduce&quot;">​</a></h2><p>Figures are generated from <code>examples/eval/jobbench_scores.json</code> and written to both <code>examples/eval/</code> and <code>docs/public/benchmarks/</code> (VitePress site assets):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/aggregate_scores.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/jobbench_scores.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> matplotlib</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/plot_jobbench_leaderboard.py</span></span></code></pre></div><p>Full methodology, per-task breakdowns, and run commands are in <a href="https://github.com/SyncLionPaw/pagent/blob/main/examples/eval/REPORT_jobbench_deepseek-v4-flash.md" target="_blank" rel="noreferrer"><code>examples/eval/REPORT_jobbench_deepseek-v4-flash.md</code></a>.</p>`,16)])])}const u=n(i,[["render",l]]);export{b as __pageData,u as default};
